function setLang(l){
  LANG=l;
  document.querySelectorAll('[data-i]').forEach(el=>{
    const k=el.dataset.i;el.innerHTML = l==='en'?EN[k]:((T[k]&&T[k][l])||EN[k]);
  });
  document.getElementById('lang').classList.remove('open');
  document.querySelectorAll('.langmenu button').forEach(b=>b.setAttribute('aria-current',b.dataset.l===l));
  document.documentElement.lang=l;
}
setLang('en');

/* ---------- buybox: size + qty + total (scoped, supports multiple per page) ---------- */
(function(){
  document.querySelectorAll('.pdp-buybox').forEach(box=>{
    const sizes=[...box.querySelectorAll('.pdp-size')];
    if(!sizes.length) return;
    const qtyEl=box.querySelector('.qval');
    const totalEl=box.closest('.pdp-info,.edit-panel')?.querySelector('.pdp-total') || box.querySelector('.pdp-total');
    let qty=1;
    function selectedPrice(){
      const sel=box.querySelector('.pdp-size.sel');
      return sel ? +sel.dataset.price : 0;
    }
    function paint(){
      const t=selectedPrice()*qty;
      if(totalEl) totalEl.textContent = isNaN(t)||t===0 ? (totalEl.dataset.fallback||'—') : '$'+t.toLocaleString();
      if(qtyEl) qtyEl.textContent=qty;
    }
    sizes.forEach(s=>s.addEventListener('click',()=>{
      sizes.forEach(x=>x.classList.remove('sel'));
      s.classList.add('sel');
      paint();
    }));
    const dec=box.querySelector('.qdec'), inc=box.querySelector('.qinc');
    if(dec) dec.addEventListener('click',()=>{qty=Math.max(1,qty-1);paint();});
    if(inc) inc.addEventListener('click',()=>{qty=Math.min(20,qty+1);paint();});
    paint();
  });
})();

/* ---------- Collection: picker + expand ---------- */
(function(){
  const cards=[...document.querySelectorAll('.ecard')];
  const stage=document.querySelector('.edit-stage');
  const detail=document.getElementById('editDetail');
  if(!cards.length || !stage || !detail) return;

  const order=cards.map(c=>c.dataset.p);
  let active=0;

  function paint(){
    cards.forEach(c=>{
      const isActive = c.dataset.p===order[active];
      c.classList.toggle('focus', isActive);
      c.classList.toggle('side', !isActive);
    });
  }
  function step(dir){ active=(active+dir+order.length)%order.length; paint(); }

  const prevBtn=document.getElementById('editPrev'), nextBtn=document.getElementById('editNext');
  if(prevBtn) prevBtn.addEventListener('click', ()=>step(-1));
  if(nextBtn) nextBtn.addEventListener('click', ()=>step(1));

  cards.forEach(c=>c.addEventListener('click', ()=>{
    if(!c.classList.contains('focus')){
      active = order.indexOf(c.dataset.p);
      paint();
      return;
    }
    openDetail(c.dataset.p);
  }));

  function openDetail(p){
    stage.style.display='none';
    document.querySelectorAll('.edit-panel').forEach(d=>{ d.hidden = d.id !== 'detail-'+p; });
    detail.classList.add('on');
    window.scrollTo({top:0, behavior:'smooth'});
  }
  const backBtn=document.getElementById('editBack');
  if(backBtn) backBtn.addEventListener('click', ()=>{
    detail.classList.remove('on');
    stage.style.display='';
  });

  paint();

  function openFromHash(){
    const h = location.hash.replace('#','');
    if(order.includes(h)){ active = order.indexOf(h); paint(); openDetail(h); }
  }
  openFromHash();
  window.addEventListener('hashchange', openFromHash);
})();

/* ---------- product detail: ingredient + usage card reveal ---------- */
(function(){
  const grids=[...document.querySelectorAll('.ing-grid,.usage-grid')];
  if(!grids.length || !('IntersectionObserver' in window)) return;
  grids.forEach(g=>g.classList.add('js-reveal'));
  const cards=grids.flatMap(g=>[...g.children]);
  const io=new IntersectionObserver((es,o)=>es.forEach(e=>{
    if(!e.isIntersecting) return;
    e.target.classList.add('in');
    o.unobserve(e.target);
  }),{threshold:.15,rootMargin:'0px 0px -6% 0px'});
  cards.forEach(c=>io.observe(c));
})();

/* ---------- product detail: image gallery swap ---------- */
(function(){
  document.querySelectorAll('.pf-gallery').forEach(g=>{
    const main = g.querySelector('.pf-main-img');
    const thumbs = [...g.querySelectorAll('.pf-thumb')];
    if(!main || !thumbs.length) return;
    thumbs.forEach(t=>t.addEventListener('click', ()=>{
      const full = t.dataset.full;
      if(full) main.src = full;
      thumbs.forEach(x=>x.classList.toggle('sel', x===t));
    }));
  });
})();
